/**
 *  Words in reading order. Lines come in the engine's order, which keeps
 *  columns together.
 */
export type OcrLine = {
	words: OcrWord[],
};

/**
 *  One recognized word, its box in the image's pixels (rounded outward, so
 *  it covers all of the word's ink).
 */
export type OcrWord = {
	text: string,
	rect: PhysicalRect,
};

/**  Where the editor's Open dialog starts. */
export type OpenStartsIn = 
/**  The folder images were last opened from (the Desktop at first). */
"lastOpened" | 
/**  The save folder. */
"saveFolder";

/**  Rust → overlays: a selection started on `monitor_index`; clear yours. */
export type OverlayClearSelection = {
	captureId: number,
	monitorIndex: number,
};

/**  Rust → overlay-n: fetch and draw this frame, then call `overlay_ready`. */
export type OverlayLoad = {
	captureId: number,
	monitorIndex: number,
	physicalBounds: PhysicalRect,
	width: number,
	height: number,
	scaleFactor: number | null,
	format: TransferFormat,
	url: string,
	dimOpacity: number | null,
	showDimensions: boolean,
	/**  Show the quick-edit toolbar on a region selection (`quickEdit.enabled`). */
	quickEdit: boolean,
	/**  Where quick edit POSTs its annotation and highlight layers. */
	layerUrl: string,
	highlightsUrl: string,
	/**
	 *  The windows on screen at capture time (visible frames, virtual-desktop
	 *  px), topmost first, for window mode (PLAN 3H). `CaptureTarget::Window`
	 *  picks one by its index here.
	 */
	windows: PhysicalRect[],
	/**
	 *  Start in window mode (the window shortcut, PLAN 3H.4), with this
	 *  window under the cursor highlighted.
	 */
	picking: boolean,
	hovered: number | null,
	/**  How many monitors there are: with one, "all screens" is just this one. */
	monitorCount: number,
};

/**
 *  Rust → overlays: the overlay on `owner` has quick-edit markup (None: none
 *  has). The others stop starting selections, so it can't be thrown away.
 */
export type OverlayMarkupOwner = {
	captureId: number,
	owner: number | null,
};

/**  Overlay → Rust: frame drawn, with the overlay-side timing. */
export type OverlayReport = {
	monitorIndex: number,
	fetchMs: number | null,
	decodeMs: number | null,
	drawMs: number | null,
	bytes: number,
};

export type OverlaySettings = {
	dimOpacity?: number | null,
	showLoupe?: boolean,
	showDimensions?: boolean,
};

/**  Rust → overlays: you're now shown; reply with `overlay_visible` once painted. */
export type OverlayShown = {
	captureId: number,
};

/**
 *  Rust → overlays: window mode is on or off, and which window (an index into
 *  `OverlayLoad::windows`) is under the pointer, so a window spanning
 *  monitors is highlighted on each of them.
 */
export type OverlayWindowPick = {
	captureId: number,
	picking: boolean,
	hovered: number | null,
};

export type PhysicalPoint = {
	x: number,
	y: number,
};

export type PhysicalRect = {
	x: number,
	y: number,
	width: number,
	height: number,
};

/**  A quick-edit toolbar action that doesn't have to end the capture. */
export type QuickAction = "copy" | "save";

/**
 *  Quick edit (PLAN Phase 2): a toolbar on the selection screen to copy, save
 *  or mark up a region capture before it's delivered.
 */
export type QuickEditSettings = {
	/**  Off: the selection screen works as in Phase 1 (Enter captures). */
	enabled?: boolean,
	/**  Ctrl+C / Copy also closes quick edit (and runs the actions still pending). */
	closeOnCopy?: boolean,
	/**  Ctrl+S / Save also closes quick edit. */
	closeOnSave?: boolean,
};

/**
 *  Quick edit's markup, as the page describes it with each action: which
 *  layers it just uploaded, its redactions, its revision, and the annotations
 *  themselves (a JSON array in virtual-desktop px) in case the editor takes
 *  over.
 */
export type QuickMarkup = {
	layer: boolean,
	highlights: boolean,
	/**  Pixelated or blurred areas in virtual-desktop px, bottom to top (PLAN 3D.4). */
	redactions: Redaction[],
	revision: number,
	annotations: string,
};

/**  What a quick-edit action did. */
export type QuickOutcome = {
	/**  Quick edit closed (per `quickEdit.closeOnCopy` / `closeOnSave`). */
	closed: boolean,
	/**  A saved file, for the toolbar's message. */
	path: string | null,
};

export type RedactMode = 
/**  Opaque black: nothing of the original survives. */
"solid" | "pixelate" | "blur";

/**  One redaction, in the base image's pixels. */
export type Redaction = {
	rect: PhysicalRect,
	mode: RedactMode,
	/**
	 *  Pixelate: block size. Blur: box radius (three passes). Source px.
	 *  Solid: unused.
	 */
	strength: number,
};

/**  Where the editor's Save As dialog starts. */
export type SaveAsStartsIn = 
/**  The folder the last Save As saved to. */
"lastSaved" | 
/**
 *  An opened image's own folder; for a capture, the folder images were
 *  last opened from.
 */
"imageFolder" | 
/**  The save folder. */
"saveFolder";

export type SaveSettings = {
	/**  May contain `%ENV%` variables. */
	directory?: string,
	/**
	 *  Tokens: `{yyyy} {MM} {dd} {HH} {mm} {ss}`, and `{n}`, `{nn}`... for
	 *  an auto number (PLAN 3H.8).
	 */
	filenameTemplate?: string,
	format?: string,
	/**  Offer a "Save" button on the capture notification when not auto-saved. */
	notificationSaveButton?: boolean,
	/**  Where the editor's Open dialog starts. */
	openStartsIn?: OpenStartsIn,
	/**  Where the editor's Save As dialog starts. */
	saveAsStartsIn?: SaveAsStartsIn,
};

export type Settings = {
	version?: number,
	hotkeys?: Hotkeys,
	/**  The markup's keys for tools and swapping colors (PLAN 3F). */
	shortcuts?: Shortcuts,
	afterCapture?: AfterCapture,
	save?: SaveSettings,
	overlay?: OverlaySettings,
	quickEdit?: QuickEditSettings,
	editor?: EditorSettings,
	/**  How the app looks (PLAN 3A). */
	appearance?: Appearance,
	/**  Style pickers for the markup tools. */
	styles?: Styles,
	startup?: Startup,
	history?: History,
	tray?: TraySettings,
	/**  Automatic updates (PLAN 3P). */
	updates?: UpdateSettings,
};

/**  Rust → all windows: settings changed (from any source), here's the new state. */
export type SettingsChanged = Settings;

/**  Rust → the settings window: show this page (a section id, e.g. "about"). */
export type SettingsShowPage = string;

/**  Human-readable, e.g. `"V"` or `"Ctrl+L"`. `None` = no shortcut. */
export type Shortcuts = {
	select?: string | null,
	pen?: string | null,
	highlighter?: string | null,
	line?: string | null,
	arrow?: string | null,
	rect?: string | null,
	ellipse?: string | null,
	text?: string | null,
	callout?: string | null,
	redact?: string | null,
	spotlight?: string | null,
	step?: string | null,
	/**  The editor's crop. */
	crop?: string | null,
	/**  Swap the two colors (PLAN 3D.15). */
	swapColors?: string | null,
};

export type Startup = {
	launchOnLogin?: boolean,
	/**
	 *  Launching Vandal (its desktop or Start menu icon). While it's running:
	 *  this. When it isn't: it starts in the tray, and opens the editor if
	 *  that's the choice, but never starts a capture. Never on login.
	 */
	launchAction?: IconAction,
};

export type Styles = {
	/**  Color presets in the user's order, `#rrggbb`. */
	palette?: string[],
	/**  How the colors show in the options bar. */
	colorControl?: ColorControl,
	/**  Line width in source px. */
	width?: NumberPicker,
	/**  The text tool's font. */
	font?: FontPicker,
	/**  The text tool's size in pt. */
	fontSize?: NumberPicker,
	/**  Redact's pixelate block size in source px (PLAN 3D.3). */
	pixelate?: NumberPicker,
	/**  Redact's blur radius in source px. */
	blur?: NumberPicker,
	/**  Spotlight's darkness outside, in % (PLAN 3D.7). */
	spotlight?: NumberPicker,
	/**  Step markers' size in source px (PLAN 3D.13). */
	stepSize?: NumberPicker,
	/**
	 *  Rounded corners (rectangles, Spotlight's rectangle) in source px (PLAN
	 *  3D.17): 0 is always a choice, and never buttons.
	 */
	cornerRadius?: NumberPicker,
	/**  Step markers' font; by default the text tool's choices. */
	stepFont?: FontPicker,
	/**  Per-tool overrides, keyed by tool id (`"highlighter"`, ...). */
	tools?: { [key in string]: ToolStyles },
};

/**  Light, dark, or following Windows. */
export type ThemeMode = "system" | "light" | "dark";

/**
 *  A tool's own palette, width picker and/or color control, used instead of
 *  the global ones.
 */
export type ToolStyles = {
	palette?: string[] | null,
	width?: NumberPicker | null,
	colorControl?: ColorControl | null,
};

/**  How frame pixels are encoded for the overlay (benchmarked in docs/perf.md). */
export type TransferFormat = 
/**  Raw RGBA bytes → `putImageData`. */
"rgba" | 
/**  Uncompressed 32bpp BMP → `createImageBitmap`. */
"bmp";

export type TraySettings = {
	/**  Clicking the tray icon (PLAN 3G). */
	clickAction?: IconAction,
};

/**  Rust → all windows: a newer version was found (not repeated for the same one). */
export type UpdateAvailable = UpdateInfo;

/**  Which releases the updater offers (PLAN 3P). */
export type UpdateChannel = 
/**  Prereleases and final releases. */
"beta" | 
/**  Final releases only. */
"stable";

/**  An update that can be installed. */
export type UpdateInfo = {
	version: string,
	currentVersion: string,
	/**  The release notes (the CHANGELOG section, Markdown). */
	notes: string,
	/**  When it was published (RFC 3339), if the manifest says. */
	date: string | null,
};

/**  Rust → all windows: the installer is downloading. */
export type UpdateProgress = {
	downloaded: number,
	total: number | null,
};

export type UpdateSettings = {
	/**
	 *  Check on startup and daily. Off: nothing is fetched unless asked for
	 *  (Richard: privacy first, their choice).
	 */
	checkAutomatically?: boolean,
	channel?: UpdateChannel,
};

/**
 *  The Windows accent color as Windows 11 apps use it: a darker shade on
 *  light backgrounds, a lighter one on dark (WinUI's AccentDark1 and
 *  AccentLight2), as `#rrggbb`.
 */
export type WindowsAccent = {
	light: string,
	dark: string,
};

/**  Rust → pages: the Windows accent changed (None: not available). */
export type WindowsAccentChanged = WindowsAccent | null;

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

